  ('approved_positioning', 'approved claims', 'Tonlita positioning', 'Tonlita helps customers reduce risk when sourcing machinery from China by supporting model selection, configuration control, factory communication, production coordination, photo/video inspections, document coordination, shipping coordination and post-sale communication.', NULL, 'approved'),
  ('unknown_info_notice', 'commercial process', 'Unknown information notice', 'If a customer asks for information that is not in the approved knowledge base, tell the seller to confirm internally before replying. English: This information is not available in the approved Tonlita knowledge base. Confirm it internally before replying. Chinese: 该信息目前不在 Tonlita 已批准的知识库中。回复客户前请先进行内部确认。', NULL, 'approved'),
  ('manager_approval_rules', 'manager-approval rules', 'Approval rules', 'Require administrator approval for exclusivity, dealer agreements, warranty exceptions, discounts, free products, free spare parts, changed payment terms, refunds, penalties, guaranteed delivery dates, major customization, unverified certification claims, legal commitments, agency rights, unconfirmed final freight, serious complaints, safety issues, customer threats or disputes.', NULL, 'approved');
